#include <bits/stdc++.h>

#define FST first
#define SND second
#define push_back bck
using namespace std;
typedef long long ll;
typedef pair<ll, ll> pll;
const int MOD_CONST = 1000000007;
vector<ll> group_list[9];
ll total_states_count, popcount_array[1 << 9], prob_array[9], aux_array[9], idx_x, idx_y, mask_state, val_x, val_m;
unordered_map<ll, ll> dp_map_state[8];

int main() {
    int n_size;
    cin >> n_size;
    for (idx_x = 0; idx_x < (1 << n_size); idx_x++) {
        idx_y = __builtin_popcount(idx_x);
        popcount_array[idx_x] = group_list[idx_y].size();
        group_list[idx_y].push_back(idx_x);
    }
    dp_map_state[0][1] = 1;
    for (idx_x = 0; idx_x < n_size; idx_x++) {
        for (idx_y = 0; idx_y < n_size; idx_y++) {
            cin >> prob_array[idx_y];
            prob_array[idx_y] = prob_array[idx_y] * 570000004 % MOD_CONST;
        }
        for (auto &state : dp_map_state[idx_x]) {
            for (int k = 0; k < n_size; k++) {
                aux_array[k] = 0;
            }
            for (auto m : group_list[idx_x]) {
                if (((state.F >> popcount_array[m]) & 1) != 0) {
                    for (int j = 0; j < n_size; j++) {
                        if (((m >> j) & 1) == 0) {
                            aux_array[j] |= (1LL << popcount_array[m | (1 << j)]);
                        }
                    }
                }
            }
            for (int msk = 0; msk < (1 << n_size); msk++) {
                val_x = 1;
                val_m = 0;
                for (int j = 0; j < n_size; j++) {
                    if (((msk >> j) & 1) != 0) {
                        val_m |= aux_array[j];
                        val_x = val_x * prob_array[j] % MOD_CONST;
                    } else {
                        val_x = val_x * (1 - prob_array[j] + MOD_CONST) % MOD_CONST;
                    }
                }
                dp_map_state[idx_x + 1][val_m] = (dp_map_state[idx_x + 1][val_m] + state.SND * val_x) % MOD_CONST;
            }
        }
    }
    cout << dp_map_state[n_size][1] << "\n";
    return 0;
}
